    {
        $keys = [];
        foreach ($fields as $path => $field) {
            $segments = explode('.', (string) $path);
            if (count($segments) > 1 || isset($field['component']) || ($field['type'] ?? null) === 'media') {
                $keys[] = $segments[0];
            }
        }

        return array_values(array_unique($keys));
